console.log(deepCopy.tags.length);  // 3

const zamowienie = {
  id: 1,
  stworzono: new Date(),
  obliczCene: () => 100,
};

const kopia = JSON.parse(JSON.stringify(zamowienie));
console.log(kopia.stworzono instanceof Date); // false - BLEDNIE, to teraz string!
console.log(kopia.obliczCene);                // undefined - BLEDNIE, funkcja ZNIKNELA!

const zamowienie = { id: 1, stworzono: new Date() };

const kopia = structuredClone(zamowienie); // POPRAWNIE - zachowuje typ Date
console.log(kopia.stworzono instanceof Date); // true

